    return UnitSpec(unit_type=unit_type, class_name=class_name, module_path=module_path, category=category, compatible_property_packages=packages or [PropertyPackageType.SEAWATER, PropertyPackageType.NACL, PropertyPackageType.NACL_T_DEP, PropertyPackageType.WATER, PropertyPackageType.MCAS, *BIOLOGICAL_LIQUID_PACKAGES], required_fixes=required_fixes or [], init_hints=InitHints(method=init_method), n_inlets=len(inlets), n_outlets=len(outlets), inlet_names=inlets, outlet_names=outlets, port_roles=port_roles or default_roles, description=description or f'Upstream WaterTAP unit model ({module_path}.{class_name})')
