def get_unit_spec(unit_type: str) -> UnitSpec:
    """Get specification for a unit type.

    Args:
        unit_type: The unit type name (e.g., "ReverseOsmosis0D")

    Returns:
        UnitSpec with full metadata

    Raises:
        KeyError: If unit type not found
    """
    if unit_type not in UNITS:
        raise KeyError(f'Unknown unit type: {unit_type}')
    return UNITS[unit_type]

def _coerce_property_package(package_ref: Optional[Any], default_property_package: PropertyPackageType) -> PropertyPackageType:
    """Resolve a package reference to the registry enum."""
    if package_ref is None:
        return default_property_package
    if isinstance(package_ref, PropertyPackageType):
        return package_ref
    if isinstance(package_ref, str):
        try:
            return PropertyPackageType[package_ref.upper()]
        except KeyError:
            for candidate in PropertyPackageType:
                if candidate.value == package_ref:
                    return candidate
    raise ValueError(f'Unknown property package reference: {package_ref}')

def _value_matches(expected: Any, actual: Any, *, set_compare: bool=False) -> bool:
    """Return True when an actual config value satisfies an expected contract value."""
    if set_compare:
        if not isinstance(actual, (list, tuple, set)):
            return False
        return set(actual) == set(expected)
    if isinstance(expected, (set, list, tuple)) and (not isinstance(expected, str)):
        return any((_value_matches(option, actual) for option in expected))
    if isinstance(expected, Enum):
        if actual == expected:
            return True
        if isinstance(actual, str):
            return actual.lower() == expected.name.lower()
        return actual == expected.value
    if isinstance(actual, Enum):
        return _value_matches(expected, actual.name)
    if isinstance(expected, str) and isinstance(actual, str):
        return expected.lower() == actual.lower()
    return expected == actual

def _matching_profiles(spec: UnitSpec, default_property_package: PropertyPackageType, config: Optional[Dict[str, Any]]=None, *, enforce_support_only: bool=False) -> List[Tuple[UnitProfile, Dict[str, Any], PropertyPackageType]]:
    """Return the ordered list of profiles satisfied by the current config."""
    user_config = dict(config or {})
    package_type = _coerce_property_package(user_config.get('property_package'), default_property_package)
    matches: List[Tuple[UnitProfile, Dict[str, Any], PropertyPackageType]] = []
    for profile in spec.profiles:
        if enforce_support_only and (not profile.enforce_support):
            continue
        if profile.property_package is not None and profile.property_package != package_type:
            continue
        merged = dict(profile.config_defaults)
        merged.update(user_config)
        if profile.allowed_config_keys:
            unknown = set(user_config) - set(profile.allowed_config_keys) - set(profile.config_defaults)
            if unknown:
                continue
        if any((not _value_matches(expected, merged.get(key)) for key, expected in profile.config_constraints.items())):
            continue
        matches.append((profile, merged, package_type))
    return matches

def supported_profiles(spec: UnitSpec) -> List[UnitProfile]:
    """Return only the strictly enforced support profiles for a unit."""
    return [profile for profile in spec.profiles if profile.enforce_support]

def unit_supports_costing_package(spec: UnitSpec, costing_package: Optional[str]=None) -> bool:
    """Return True when a unit is upstream-costable for the requested package."""
    if not spec.costing.supported:
        return False
    if costing_package is None:
        return True
    return costing_package in spec.costing.supported_packages

def costing_supported_units(costing_package: Optional[str]=None) -> List[str]:
    """Return unit types with certified upstream-backed costing support."""
    return sorted((unit_type for unit_type, spec in UNITS.items() if unit_supports_costing_package(spec, costing_package)))

def resolve_unit_support(spec: UnitSpec, default_property_package: PropertyPackageType, config: Optional[Dict[str, Any]]=None, session_package_config: Optional[Dict[str, Any]]=None) -> Tuple[Dict[str, Any], PropertyPackageType, Optional[UnitProfile]]:
    """Apply support-profile defaults and reject unsupported permutations."""
    user_config = dict(config or {})
    package_type = _coerce_property_package(user_config.get('property_package'), default_property_package)
    if package_type not in spec.compatible_property_packages:
        compatible = ', '.join((pkg.name for pkg in spec.compatible_property_packages))
        raise ValueError(f'{spec.unit_type} is not supported with property package {package_type.name}. Compatible packages: {compatible}')
    profiles = supported_profiles(spec)
    if not profiles:
        return (user_config, package_type, None)
    matches = _matching_profiles(spec, default_property_package, user_config, enforce_support_only=True)
    if len(matches) > 1 and session_package_config is not None:
        filtered_matches = []
        for profile, normalized_config, profile_package in matches:
            try:
                normalize_profile_package_config(profile, session_package_config)
            except ValueError:
                continue
            filtered_matches.append((profile, normalized_config, profile_package))
        if filtered_matches:
            matches = filtered_matches
    if len(matches) > 1:
        raise ValueError(f'{spec.unit_type} config matches multiple support profiles. Tighten the unit config contract in the registry.')
    if not matches:
        descriptions = []
        for profile in profiles:
            package_name = profile.property_package.name if profile.property_package is not None else package_type.name
            descriptions.append(f'{profile.name} (property_package={package_name}, config={profile.config_constraints or profile.config_defaults})')
        raise ValueError(f'{spec.unit_type} only supports the following public profile(s): ' + '; '.join(descriptions))
    profile, normalized_config, profile_package = matches[0]
    if profile.require_session_default_package and profile_package != default_property_package:
        raise ValueError(f'{spec.unit_type} requires the session default property package to be {profile_package.name}; unit-level property_package overrides are not supported for this public profile')
    return (normalized_config, profile_package, profile)

def _engineering_input_key(variable_name: str) -> str:
    """Derive a stable client-facing key from a model variable path."""
    key = variable_name
    key = key.replace('.', '_')
    key = key.replace('*', 'all')
    key = key.replace('[', '_').replace(']', '')
    key = key.replace(',', '_')
    key = re.sub('_+', '_', key).strip('_')
    key = key.replace('0_', '')
    if key.endswith('_0'):
        key = key[:-2]
    return key

def _engineering_input_kind(variable_name: str, description: str) -> str:
    """Infer a process-facing engineering input category from registry metadata."""
    haystack = f'{variable_name} {description}'.lower()
    if any((token in haystack for token in ('area', 'length', 'width', 'height', 'depth', 'diam', 'diameter', 'thickness', 'cell_pair_num', 'number_columns', 'bed_depth', 'channel_height'))):
        return 'design_size'
    if any((token in haystack for token in ('permeability', 'diffusivity', 'langmuir', 'capacity', 'resistance', 'porosity', 'charge_density', 'dielectric', 'radius_pore', 'a_comp', 'b_comp', 'membrane', 'resin'))):
        return 'material_or_equipment_property'
    if any((token in haystack for token in ('cp_modulus', 'recovery', 'utilization', 'efficiency', 'split_fraction', 'delta_temperature', 'uv dose', 'current', 'voltage'))):
        return 'performance_assumption'
    if any((token in haystack for token in ('pressure', 'temperature', 'flow', 'velocity', 'deltap'))):
        return 'operating_condition'
    return 'performance_assumption'

def _engineering_input_from_variable_spec(variable_spec: VariableSpec) -> EngineeringInputSpec:
    """Compile a registry VariableSpec into a default public engineering input."""
    return EngineeringInputSpec(key=_engineering_input_key(variable_spec.name), target_variable=variable_spec.name, description=variable_spec.description, units=variable_spec.units, kind=_engineering_input_kind(variable_spec.name, variable_spec.description), typical_min=variable_spec.typical_min, typical_max=variable_spec.typical_max, typical_default=variable_spec.typical_default, indexed=variable_spec.indexed, satisfaction_mode=variable_spec.satisfaction_mode)

def effective_engineering_inputs(spec: UnitSpec, default_property_package: PropertyPackageType, config: Optional[Dict[str, Any]]=None) -> List[EngineeringInputSpec]:
    """Return the public engineering inputs for a unit/profile match."""
    matches = _matching_profiles(spec, default_property_package, config)
    for profile, _, _ in matches:
        if profile.engineering_inputs:
            return list(profile.engineering_inputs)
        if profile.required_fixes is not None:
            return [_engineering_input_from_variable_spec(variable_spec) for variable_spec in profile.required_fixes]
    if spec.engineering_inputs:
        return list(spec.engineering_inputs)
    return [_engineering_input_from_variable_spec(variable_spec) for variable_spec in spec.required_fixes]

def resolve_engineering_input(engineering_inputs: List[EngineeringInputSpec], raw_key: str) -> Tuple[Optional[EngineeringInputSpec], Optional[str], Optional[str]]:
    """Resolve one client-supplied engineering input key.

    Returns the matched engineering spec, the key to persist in session state,
    and the concrete variable path to compile into an internal fix.
    """
    by_key = {item.key: item for item in engineering_inputs}
    by_target = {item.target_variable: item for item in engineering_inputs}
    input_spec = by_key.get(raw_key) or by_target.get(raw_key)
    if input_spec is not None:
        return (input_spec, input_spec.key, input_spec.target_variable)
    for candidate in engineering_inputs:
        if not candidate.indexed:
            continue
        base = candidate.target_variable.split('[', 1)[0]
        if raw_key.startswith(f'{base}['):
            return (candidate, raw_key, raw_key)
    return (None, None, None)

def compile_engineering_inputs(spec: UnitSpec, default_property_package: PropertyPackageType, config: Optional[Dict[str, Any]], provided_inputs: Optional[Dict[str, float]]) -> Dict[str, float]:
    """Compile client-facing engineering inputs into internal variable fixes."""
    compiled: Dict[str, float] = {}
    if not provided_inputs:
        return compiled
    engineering_inputs = effective_engineering_inputs(spec, default_property_package, config)
    for key, value in provided_inputs.items():
        input_spec, _, compiled_target = resolve_engineering_input(engineering_inputs, key)
        if input_spec is None:
            if spec.unit_type == 'ReverseOsmosis0D' and key in {'recovery', 'recovery_vol_phase[0,Liq]', 'recovery_vol_phase[0.0,Liq]'}:
                compiled['recovery_vol_phase[0,Liq]'] = value
                continue
            valid = sorted((item.key for item in engineering_inputs))
            raise ValueError(f"Unknown engineering input '{key}' for {spec.unit_type}. Valid engineering inputs: {valid}")
        compiled[compiled_target or input_spec.target_variable] = value
    return compiled

def effective_required_fixes(spec: UnitSpec, default_property_package: PropertyPackageType, config: Optional[Dict[str, Any]]=None) -> List[VariableSpec]:
    """Return the profile-matched required fixes for a unit config."""
    matches = _matching_profiles(spec, default_property_package, config)
    for profile, _, _ in matches:
        if profile.required_fixes is not None:
            return list(profile.required_fixes)
    return list(spec.required_fixes)

def unit_input_contract_summary(spec: UnitSpec, default_property_package: Optional[PropertyPackageType]=None, config: Optional[Dict[str, Any]]=None) -> Dict[str, Any]:
    """Return the process-facing input contract status for one unit.

    The summary is intentionally explicit even when a unit has no agent-facing
    engineering inputs. That lets MCP clients distinguish database-backed ZO
    units, feed/product endpoints, connection-defined hydraulic units, and
    true remaining topology-preflight gaps.
    """
    package = default_property_package or spec.compatible_property_packages[0]
    try:
        engineering_inputs = effective_engineering_inputs(spec, package, config)
        profiles = _matching_profiles(spec, package, config)
    except Exception as exc:
        return {'mode': 'unsupported_config', 'complete': False, 'requires_agent_inputs': True, 'engineering_input_count': 0, 'auto_fixed_variable_count': 0, 'reason': str(exc), 'next_step': 'Use get_unit_requirements with a supported property_package/config pair.'}
    auto_fixed_count = sum((len(profile.auto_fixed_variables) for profile, _, _ in profiles))
    if engineering_inputs:
        return {'mode': 'engineering_inputs', 'complete': True, 'requires_agent_inputs': True, 'engineering_input_count': len(engineering_inputs), 'auto_fixed_variable_count': auto_fixed_count, 'reason': 'Unit exposes process-facing engineering inputs.', 'next_step': 'Provide values with set_unit_engineering_inputs or units[].engineering_inputs.'}
    if PropertyPackageType.ZERO_ORDER in spec.compatible_property_packages or '.zero_order.' in spec.module_path:
        return {'mode': 'database_parameters', 'complete': True, 'requires_agent_inputs': False, 'engineering_input_count': 0, 'auto_fixed_variable_count': auto_fixed_count, 'reason': 'Zero-order unit parameters are loaded from the WaterTAP database.', 'next_step': 'Call load_zo_parameters or build through a zero-order topology/template path.'}
    if spec.category in {UnitCategory.FEED, UnitCategory.FEED_ZO}:
        return {'mode': 'feed_state', 'complete': True, 'requires_agent_inputs': False, 'engineering_input_count': 0, 'auto_fixed_variable_count': auto_fixed_count, 'reason': 'Feed units are specified by feed-state tools, not engineering inputs.', 'next_step': 'Call set_feed_state for each feed unit.'}
    if spec.category == UnitCategory.PRODUCT:
        return {'mode': 'product_sink', 'complete': True, 'requires_agent_inputs': False, 'engineering_input_count': 0, 'auto_fixed_variable_count': auto_fixed_count, 'reason': 'Product units are terminal sinks and do not add process DOF.', 'next_step': 'Connect upstream product/effluent ports to this unit.'}
    if profiles and all((profile.required_fixes == [] for profile, _, _ in profiles)):
        return {'mode': 'profile_declares_no_external_dof', 'complete': True, 'requires_agent_inputs': False, 'engineering_input_count': 0, 'auto_fixed_variable_count': auto_fixed_count, 'reason': 'The matched support profile declares no external unit DOF.', 'next_step': 'Provide connected feed states and solve through the server pipeline.'}
    if spec.init_hints is not None and spec.init_hints.method == InitMethod.NONE and (not spec.required_fixes):
        return {'mode': 'connection_defined', 'complete': True, 'requires_agent_inputs': False, 'engineering_input_count': 0, 'auto_fixed_variable_count': auto_fixed_count, 'reason': 'Unit behavior is determined by connected inlet states and internal equations.', 'next_step': 'Connect all inlet/outlet ports and set feed states.'}
    if auto_fixed_count:
        return {'mode': 'profile_auto_fixed', 'complete': True, 'requires_agent_inputs': False, 'engineering_input_count': 0, 'auto_fixed_variable_count': auto_fixed_count, 'reason': 'The matched support profile fixes all remaining unit DOF server-side.', 'next_step': 'Build through the server pipeline; profile auto-fixes are applied at model build.'}
    return {'mode': 'topology_preflight', 'complete': False, 'requires_agent_inputs': True, 'engineering_input_count': 0, 'auto_fixed_variable_count': auto_fixed_count, 'reason': 'No curated process-facing input contract is registered yet for this unit/profile.', 'next_step': 'Use plan_topology or get_dof_completion_plan; promote recurring live DOF to registry engineering_inputs.'}

def normalize_profile_package_config(profile: UnitProfile, package_config: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Validate and normalize session package config for a support profile."""
    config = dict(package_config or {})
    missing = [key for key in profile.required_session_package_config if config.get(key) is None]
    if missing:
        raise ValueError(f'{profile.name} requires property_package_config keys: {missing}')
    for key, expected in profile.session_package_config_constraints.items():
        actual = config.get(key)
        if not _value_matches(expected, actual):
            raise ValueError(f"{profile.name} requires property_package_config['{key}']={expected!r}, received {actual!r}")
    if profile.required_solutes:
        actual_solutes = config.get('solute_list')
        if profile.allow_additional_solutes:
            if not isinstance(actual_solutes, (list, tuple, set)):
                raise ValueError(f"{profile.name} requires property_package_config['solute_list'] to be a list-like collection")
            missing_solutes = [solute for solute in profile.required_solutes if solute not in actual_solutes]
            if missing_solutes:
                raise ValueError(f'{profile.name} requires solute_list to include {profile.required_solutes}, missing {missing_solutes} from {actual_solutes!r}')
        elif not _value_matches(profile.required_solutes, actual_solutes, set_compare=True):
            raise ValueError(f'{profile.name} requires solute_list={profile.required_solutes}, received {actual_solutes!r}')
        required_component_fields = [field_name for field_name in ('charge', 'mw_data', 'stokes_radius_data', 'molar_volume_data') if field_name in profile.required_session_package_config]
        for field_name in required_component_fields:
            field = config.get(field_name)
            if not isinstance(field, dict):
                raise ValueError(f"{profile.name} requires property_package_config['{field_name}'] to be a dict")
            missing_species = [solute for solute in profile.required_solutes if solute not in field]
            if missing_species:
                raise ValueError(f'{profile.name} requires {field_name} entries for {missing_species}')
        phase_component_fields = [field_name for field_name in ('diffusivity_data', 'elec_mobility_data') if field_name in profile.required_session_package_config]
        for field_name in phase_component_fields:
            field_data = config.get(field_name)
            if not isinstance(field_data, dict):
                raise ValueError(f"{profile.name} requires property_package_config['{field_name}'] to be a dict")
            missing_phase_component = []
            for solute in profile.required_solutes:
                if solute in field_data:
                    continue
                if ('Liq', solute) in field_data:
                    continue
                missing_phase_component.append(solute)
            if missing_phase_component:
                raise ValueError(f"{profile.name} requires {field_name} entries for {missing_phase_component}. Use component keys or ('Liq', component) tuple keys.")
    if profile.package_config_normalizer == 'mcas_dspmde_5ion':
        mw_data = dict(config.get('mw_data', {}))
        mw_data.setdefault('H2O', 0.018)
        config['mw_data'] = mw_data
        diffusivity = {}
        for key, value in config.get('diffusivity_data', {}).items():
            if isinstance(key, tuple):
                diffusivity[key] = value
            else:
                diffusivity['Liq', key] = value
        config['diffusivity_data'] = diffusivity
    return config

def list_units(category: Optional[UnitCategory]=None, property_package: Optional[PropertyPackageType]=None, is_idaes: Optional[bool]=None) -> List[UnitSpec]:
    """List units with optional filtering.

    Args:
        category: Filter by unit category
        property_package: Filter by compatible property package
        is_idaes: Filter by whether unit is from IDAES

    Returns:
        List of matching UnitSpec objects
    """
    results = list(UNITS.values())
    if category is not None:
        results = [u for u in results if u.category == category]
    if property_package is not None:
        results = [u for u in results if property_package in u.compatible_property_packages]
    if is_idaes is not None:
        results = [u for u in results if u.is_idaes_unit == is_idaes]
    return results

def get_import_statement(unit_type: str) -> str:
    """Generate Python import statement for a unit.

    Args:
        unit_type: The unit type name

    Returns:
        Python import statement string
    """
    spec = get_unit_spec(unit_type)
    return f'from {spec.module_path} import {spec.class_name}'
